const DEEP={"css_uutien":{"t":"CSS: ai thắng khi nhiều quy tắc cùng chọn một phần tử?","tags":["css-uutien","css-specificity","css-ke-thua","css"],"intro":"Bạn hay nhầm vì cứ nghĩ \"quy tắc viết sau luôn thắng\" hoặc \"nhiều lớp thì thắng một id\". Thực ra trình duyệt xét theo một thang bậc cố định, và chỉ khi hai quy tắc ngang nhau mới nhìn đến thứ tự viết.","steps":[{"h":"Thang bậc ưu tiên","p":["Trình duyệt xét từ trên xuống. Gặp tầng nào phân được thắng bại thì dừng, không xét tầng sau.","Tầng 3 (trọng số bộ chọn) là nơi hay xảy ra nhầm lẫn nhất nên ta học kĩ ở bước sau."],"fig":"css_uutien"},{"h":"Tính trọng số: cộng dồn từng phần","p":["Mỗi id (#) được 100, mỗi lớp (.), lớp giả (:hover), thuộc tính ([type]) được 10, mỗi tên thẻ và phần tử giả (::first-line) được 1. Các ký hiệu *, >, +, ~ không có điểm.","Tính xong thì so sánh con số: lớn hơn thì thắng. Con số này CỘNG DỒN nên 11 lớp = 110 vẫn lớn hơn 1 id = 100."],"fig":"css_trongso"},{"h":"Ví dụ từng bước","p":["Cho HTML: <p id=\"b\" class=\"a\">Xin chào<\/p> và CSS: p {color:blue} .a {color:green} #b {color:red}.","Trọng số: p = 1, .a = 10, #b = 100 → #b thắng, chữ đỏ. Dù viết .a sau cùng, nó vẫn chỉ có 10 điểm.","Nếu thêm .a {color:black !important} thì chữ đen: !important đứng tầng 1, thắng mọi trọng số."],"code":"p {color:blue}\n.a {color:green}\n#b {color:red}\n/* <p id=\"b\" class=\"a\"> → chữ màu đỏ */","lang":"css"},{"h":"Bằng nhau thì sao?","p":["Khi hai trọng số bằng nhau (ví dụ .box p = 11 và p.note = 11) thì quy tắc viết SAU thắng.","Thuộc tính style=\"…\" trong thẻ luôn thắng quy tắc dùng bộ chọn (trừ !important). Kế thừa (như color từ thẻ cha) là yếu nhất: quy tắc nhắm trực tiếp vào phần tử luôn thắng giá trị kế thừa."]}],"traps":[["Quy tắc viết sau luôn thắng.","Chỉ thắng khi cùng trọng số (và cùng tầng ưu tiên)."],["Nhiều lớp đánh bại được id.","Cộng dồn: 11 lớp = 110 > 100, nhưng 9 lớp = 90 < 100. Hãy tính ra số."],["Quên cộng tên thẻ trong bộ chọn con cháu (ul li a = 3).","Mỗi tên thẻ được 1 điểm."]],"tip":"Mẹo nhớ \"1-10-100\": thẻ – lớp – id. Gặp bài so sánh, hãy viết ra tổng điểm của từng bộ chọn trước khi trả lời.","min":5},"css_box":{"t":"CSS: mô hình hộp (margin – border – padding – content)","tags":["css-box"],"intro":"Bạn hay nhầm vì khó hình dung phần nào nằm trong, phần nào nằm ngoài viền, và vì sao lề dọc \"biến mất\" một phần.","steps":[{"h":"Bốn lớp của một hộp","p":["Mỗi phần tử là một chiếc hộp gồm 4 lớp, từ trong ra ngoài: content (nội dung) → padding (đệm) → border (viền) → margin (lề).","Padding nằm TRONG viền và có màu nền của phần tử; margin nằm NGOÀI viền và trong suốt."],"fig":"css_box"},{"h":"Tính bề rộng","p":["Mặc định (content-box): width chỉ là bề rộng nội dung. Bề rộng chiếm chỗ = width + 2×padding + 2×border.","Ví dụ width 300px, padding 20px, border 5px → 300 + 40 + 10 = 350px (margin tính thêm bên ngoài).","Với box-sizing: border-box thì width đã gồm cả padding và border: nội dung chỉ còn 300 − 40 − 10 = 250px."]},{"h":"Lề dọc liền kề thì gộp","p":["Hai khối nằm trên dưới nhau, margin-bottom 40px của khối trên và margin-top 25px của khối dưới KHÔNG cộng thành 65px. Chúng gộp lại và lấy số lớn hơn: khoảng cách là 40px.","Lề ngang (trái/phải) không gộp."]},{"h":"Viết tắt padding và margin","p":["4 giá trị: trên – phải – dưới – trái (theo chiều kim đồng hồ). 2 giá trị: trên/dưới rồi trái/phải. 1 giá trị: cả bốn phía.","margin: 0 auto trên khối có width cố định sẽ căn khối ra giữa theo chiều ngang."],"code":"padding: 5px 10px 15px 20px; /* trên phải dưới trái */\nmargin: 10px 20px;           /* trên-dưới 10, trái-phải 20 */","lang":"css"}],"traps":[["Margin nằm trong viền.","Margin ở NGOÀI viền; trong viền là padding."],["Lề dọc liền kề cộng dồn.","Gộp lại, lấy giá trị lớn hơn."],["width là tổng bề rộng của hộp.","Chỉ đúng khi box-sizing: border-box."]],"tip":"Nhớ thứ tự bằng câu: \"Nội – Đệm – Viền – Lề\" (từ trong ra). Gặp bài tính kích thước, hãy vẽ nhanh bốn lớp rồi cộng từng lớp.","min":5},"css_selector":{"t":"CSS: bộ chọn – chọn đúng phần tử","tags":["css-selector","css-pseudo"],"intro":"Bạn hay nhầm giữa dấu cách (con cháu) với dấu > (con trực tiếp), hay giữa \".a .b\" và \".a.b\".","steps":[{"h":"Đọc bộ chọn từ phải sang trái","p":["Bộ chọn \"div.box p\" nghĩa là: phần tử p NẰM TRONG (ở mọi cấp) một div có lớp box. Phần tử được chọn luôn là phần tử đứng cuối cùng."],"fig":"css_tree"},{"h":"Bảng các quan hệ","p":["A B : B là con cháu của A (mọi cấp). A > B : B là con TRỰC TIẾP của A. A + B : B đứng liền ngay sau A. A ~ B : mọi B cùng cấp đứng sau A. A, B : chọn cả A lẫn B.",".a.b (viết liền): CÙNG MỘT phần tử có cả hai lớp a và b. .a .b (có dấu cách): phần tử lớp b nằm trong phần tử lớp a."]},{"h":"Lớp giả và phần tử giả","p":["Lớp giả viết MỘT dấu hai chấm: a:hover (đang trỏ chuột), li:first-child (là con đầu của cha), a:link (liên kết chưa thăm).","Phần tử giả viết HAI dấu hai chấm: p::first-line (dòng đầu), p::first-letter (chữ cái đầu)."]},{"h":"Thử với ví dụ","p":["Cho <div><p>1<\/p><span><p>2<\/p><\/span><\/div>. Bộ chọn div > p chỉ chọn đoạn 1 (đoạn 2 là cháu). Bộ chọn div p chọn cả hai đoạn."],"code":"div > p { color: red; }   /* chỉ đoạn 1 */\ndiv p   { color: blue; }  /* cả đoạn 1 và 2 */","lang":"css"}],"traps":[["div p và div > p giống nhau.","Dấu cách: mọi cấp; dấu >: chỉ con trực tiếp."],[".a .b và .a.b giống nhau.","Có dấu cách là hai phần tử khác nhau; viết liền là một phần tử."],["p:first-line (một dấu :).","Phần tử giả cần hai dấu: p::first-line."]],"tip":"Quy tắc đọc: luôn đọc từ phải sang trái để biết phần tử nào bị chọn.","min":5},"css_flex":{"t":"CSS: Flexbox, định vị và đơn vị","tags":["css-khung"],"intro":"Bạn hay nhầm justify-content với align-items, và nhầm các kiểu position.","steps":[{"h":"Hai trục của Flexbox","p":["Trục chính là hướng các mục xếp hàng: với flex-direction: row là ngang, với column là dọc. Trục phụ vuông góc với trục chính.","justify-content căn theo trục CHÍNH; align-items căn theo trục PHỤ. Đổi flex-direction thì hai trục đổi vai trò."],"fig":"css_flex"},{"h":"Các kiểu position","p":["relative: dịch so với vị trí gốc của chính nó. absolute: định vị theo tổ tiên gần nhất có position khác static (không có thì theo trang). fixed: gắn với khung nhìn, đứng yên khi cuộn."]},{"h":"Đơn vị tương đối","p":["em tính theo cỡ chữ của phần tử cha (cha 20px, con 1.5em → 30px). rem tính theo cỡ chữ gốc của html (html 16px, 2rem → 32px). % tính theo kích thước phần tử cha."]},{"h":"Thiết kế đáp ứng","p":["@media (max-width: 600px) {…} chỉ áp dụng khi khung nhìn rộng không quá 600px. flex-wrap: wrap cho các mục xuống dòng khi hết chỗ."],"code":".menu { display:flex; justify-content:space-between; flex-wrap:wrap; }\n@media (max-width:600px) { .menu { flex-direction:column; } }","lang":"css"}],"traps":[["align-items luôn căn theo chiều dọc.","Theo trục PHỤ: với column thì là chiều ngang."],["absolute luôn theo thẻ body.","Theo tổ tiên gần nhất có position khác static."],["em tính theo cỡ chữ gốc.","em theo cha, rem theo gốc."]],"tip":"Trước khi chọn justify hay align, hãy hỏi: \"trục chính của mình đang hướng nào?\"","min":5},"html_table":{"t":"HTML: bảng có ô gộp (colspan, rowspan)","tags":["html-bang"],"intro":"Bạn hay đếm sai số thẻ td vì quên rằng ô gộp chiếm chỗ ở các hàng, cột khác.","steps":[{"h":"Vẽ lưới trước","p":["Một bảng là lưới gồm các hàng và cột. Trước khi viết mã hãy vẽ lưới ra giấy, rồi tô các ô gộp.","colspan=\"2\" gộp hai ô nằm cạnh nhau trong một hàng; rowspan=\"2\" gộp hai ô xếp trên dưới nhau trong một cột."],"fig":"html_bang"},{"h":"Đếm thẻ td từng hàng","p":["Mỗi thẻ tr là một hàng của mã nguồn. Số thẻ td/th cần viết trong hàng = số cột của lưới − số ô đã bị ô gộp ở hàng trên chiếm chỗ.","Trong hình: hàng 3 có 2 thẻ (một thẻ là ô rowspan=\"2\"); hàng 4 chỉ cần 1 thẻ td vì cột 1 của nó đã bị ô rowspan ở hàng 3 chiếm chỗ."]},{"h":"Các thẻ liên quan","p":["table › tr (hàng) › td (ô dữ liệu) hoặc th (ô tiêu đề). caption là tiêu đề của bảng, đặt ngay sau thẻ table. Danh sách: ul (không thứ tự), ol (có thứ tự), li là từng mục."],"code":"<table>\n  <caption>Điểm<\/caption>\n  <tr><th colspan=\"2\">Điểm<\/th><\/tr>\n  <tr><td>Toán<\/td><td>9<\/td><\/tr>\n<\/table>","lang":"html"}],"traps":[["Số td mỗi hàng luôn bằng số cột.","Ô gộp chiếm chỗ nên có hàng ít thẻ hơn."],["rowspan gộp các ô nằm ngang.","rowspan gộp theo chiều DỌC; colspan gộp theo chiều ngang."]],"tip":"Muốn không sai: vẽ lưới, gạch các ô bị chiếm rồi mới đếm.","min":5},"html_form":{"t":"HTML: biểu mẫu (form)","tags":["html-bieumau","forms","html-lienket"],"intro":"Bạn hay nhầm id với name, và nhầm khi nào dữ liệu được gửi đi.","steps":[{"h":"label – input: liên kết bằng for và id","p":["Thuộc tính for của label phải TRÙNG id của ô nhập. Khi đó nháy vào chữ nhãn thì con trỏ vào ô nhập, rất tiện cho người dùng."],"fig":"forms"},{"h":"Nhóm radio và name","p":["Các nút radio cần CÙNG name thì mới thành một nhóm chỉ chọn được một. Giá trị gửi lên máy chủ dựa vào name và value, không dựa vào id."]},{"h":"Ba thuộc tính dễ nhầm","p":["required: bắt buộc nhập trước khi gửi. readonly: không sửa được nhưng VẪN được gửi. disabled: không sửa được và KHÔNG được gửi đi."]},{"h":"Liên kết trong trang","p":["<a href=\"#muc2\"> nhảy tới phần tử có id=\"muc2\" trong cùng trang. target=\"_blank\" mở liên kết ở tab mới. Liên kết ra website khác dùng đường dẫn tuyệt đối (https://…)."],"code":"<a href=\"#muc2\">Tới mục 2<\/a>\n<h2 id=\"muc2\">Mục 2<\/h2>","lang":"html"}],"traps":[["Dữ liệu gửi đi theo id.","Theo name."],["disabled và readonly giống nhau.","disabled không gửi giá trị; readonly vẫn gửi."],["Hai radio khác name vẫn chỉ chọn được một.","Chỉ cùng name mới thành nhóm."]],"tip":"Nhớ: id để CSS/JS/label tìm phần tử; name để gửi dữ liệu.","min":5},"sql_group":{"t":"SQL: GROUP BY, HAVING và thứ tự xử lí","tags":["S4","sql-group","S1","S2","S3","S5","S7","S10","sql-aggregate","sql-co-ban"],"intro":"Bạn hay nhầm khi nào dùng WHERE, khi nào dùng HAVING, và chọn thêm cột không có trong GROUP BY.","steps":[{"h":"SQL xử lí theo một thứ tự khác với thứ tự viết","p":["Dù bạn viết SELECT đầu tiên, máy xử lí theo thứ tự: FROM/JOIN (lấy bảng) → WHERE (lọc dòng) → GROUP BY (gom nhóm) → HAVING (lọc nhóm) → SELECT → ORDER BY.","Vì thế lúc WHERE chạy, các nhóm và hàm tổng hợp CHƯA tồn tại."],"fig":"sql_pipeline"},{"h":"GROUP BY: nhiều dòng thành một dòng cho mỗi nhóm","p":["Với bảng HocSinh(Ten, Lop), GROUP BY Lop gom các dòng cùng lớp lại, rồi hàm tổng hợp COUNT(*) đếm số dòng của mỗi nhóm.","Trong SELECT chỉ được đặt: cột có trong GROUP BY, hoặc hàm tổng hợp (COUNT, SUM, AVG, MAX, MIN)."],"fig":"sql_group"},{"h":"WHERE hay HAVING?","p":["Điều kiện về từng DÒNG (Lop = \"12A1\", Diem >= 5) → WHERE, viết trước GROUP BY.","Điều kiện về cả NHÓM, có hàm tổng hợp (COUNT(*) > 2, AVG(Diem) >= 8) → HAVING, viết sau GROUP BY."],"code":"SELECT Lop, COUNT(*) AS SiSo\nFROM HocSinh\nWHERE Gioi = \"Nữ\"          -- lọc dòng trước\nGROUP BY Lop\nHAVING COUNT(*) > 2;        -- lọc nhóm sau","lang":"sql"},{"h":"Cẩn thận với COUNT","p":["COUNT(*) đếm số dòng; COUNT(cột) bỏ qua giá trị NULL; COUNT(DISTINCT cột) đếm số giá trị khác nhau. Muốn hỏi \"có bao nhiêu học sinh khác nhau\" hãy dùng DISTINCT."]}],"traps":[["WHERE COUNT(*) > 2.","Hàm tổng hợp phải đặt trong HAVING."],["SELECT Ten, COUNT(*) … GROUP BY Lop.","Ten không nằm trong GROUP BY và không có hàm tổng hợp: không hợp lệ."],["HAVING viết trước GROUP BY.","Thứ tự viết: WHERE → GROUP BY → HAVING → ORDER BY."]],"tip":"Câu hỏi mẹo: \"điều kiện này nói về một dòng hay về cả nhóm?\" Dòng → WHERE, nhóm → HAVING.","min":5},"sql_join":{"t":"SQL: liên kết bảng và tìm \"chưa có\"","tags":["sql-join"],"intro":"Bạn hay nhầm INNER JOIN với LEFT JOIN, và viết = NULL khi tìm đối tượng chưa xuất hiện.","steps":[{"h":"INNER JOIN và LEFT JOIN","p":["INNER JOIN chỉ giữ những dòng khớp ở CẢ HAI bảng. LEFT JOIN giữ MỌI dòng bảng bên trái; dòng không khớp có giá trị NULL ở các cột của bảng phải.","Điều kiện nối thường là khoá ngoài = khoá chính (ON Sach.MaSach = MuonSach.MaSach)."],"fig":"sql_join"},{"h":"Bài toán \"chưa từng…\"","p":["Muốn tìm \"sách chưa ai mượn\": LEFT JOIN từ Sach sang MuonSach, rồi giữ các dòng có cột của MuonSach là NULL.","Phải viết IS NULL. So sánh = NULL không bao giờ đúng, vì NULL nghĩa là \"không biết\"."],"code":"SELECT s.TenSach\nFROM Sach s LEFT JOIN MuonSach m ON s.MaSach = m.MaSach\nWHERE m.MaSach IS NULL;","lang":"sql"},{"h":"Cách khác: NOT IN","p":["Có thể viết: WHERE MaSach NOT IN (SELECT MaSach FROM MuonSach). Cách này dễ đọc nhưng cần chắc rằng truy vấn con không chứa NULL."]}],"traps":[["INNER JOIN vẫn giữ sách chưa ai mượn.","INNER JOIN bỏ các dòng không khớp."],["WHERE m.MaSach = NULL.","Phải là IS NULL."],["Đặt điều kiện IS NULL trên cột của bảng trái.","Phải lọc trên cột của bảng PHẢI (bảng bị thiếu)."]],"tip":"Khi đề nói \"chưa\", \"không có\", \"không bao giờ\" → nghĩ ngay LEFT JOIN + IS NULL.","min":5},"sql_sub":{"t":"SQL: truy vấn con và \"cao nhất trong phạm vi\"","tags":["sql-subquery","S6"],"intro":"Bạn hay lấy MAX của toàn bảng thay vì MAX trong cùng phạm vi lọc, hoặc dùng MAX trực tiếp trong WHERE.","steps":[{"h":"Truy vấn con là một câu SELECT nằm trong ngoặc","p":["Truy vấn con tính ra một giá trị (hoặc một tập giá trị) rồi truy vấn ngoài dùng nó để so sánh: = , > với một giá trị; IN, NOT IN với nhiều giá trị."]},{"h":"Cùng phạm vi lọc","p":["\"Học sinh có điểm Tin cao nhất\" → điểm cao nhất của MÔN TIN, không phải điểm cao nhất của cả bảng (có thể thuộc môn khác).","Điều kiện lọc của truy vấn con phải giống điều kiện của truy vấn ngoài (cùng môn, cùng lớp, cùng năm học…)."],"code":"SELECT MaHS, Diem\nFROM KQ\nWHERE Mon = \"Tin\"\n  AND Diem = (SELECT MAX(Diem) FROM KQ WHERE Mon = \"Tin\");","lang":"sql"},{"h":"Vì sao không viết WHERE Diem = MAX(Diem)?","p":["Hàm tổng hợp chưa tồn tại lúc WHERE chạy (xem thứ tự xử lí). Phải dùng truy vấn con, hoặc ORDER BY Diem DESC LIMIT 1 (nhưng chỉ lấy một người, bỏ sót đồng hạng).","Dùng = với MAX sẽ trả về mọi học sinh đồng điểm cao nhất."]}],"traps":[["Bỏ điều kiện môn trong truy vấn con.","MAX toàn bảng có thể không thuộc môn đang xét → kết quả rỗng hoặc sai."],["WHERE Diem = MAX(Diem).","Dùng truy vấn con."],["LIMIT 1 luôn đúng.","Bỏ sót các học sinh đồng hạng."]],"tip":"Truy vấn con \"kế thừa\" cùng WHERE với truy vấn ngoài: hãy chép điều kiện sang.","min":5},"csdl_key":{"t":"CSDL: khoá chính, khoá ngoài, ràng buộc","tags":["csdl-khoa","S9","sql-rangbuoc","csdl-kieu","S8"],"intro":"Bạn hay nhầm vai trò của khoá ngoài, hoặc không biết vì sao thêm hay xoá một dòng bị từ chối.","steps":[{"h":"Hai loại khoá","p":["Khoá chính: xác định duy nhất mỗi bản ghi, không được trống, không được trùng; có thể gồm nhiều trường.","Khoá ngoài: trường của bảng này tham chiếu tới khoá chính của bảng khác, tạo liên kết giữa hai bảng. Giá trị khoá ngoài có thể trùng nhau."],"fig":"csdl_khoa"},{"h":"Ràng buộc toàn vẹn tham chiếu","p":["Không thể THÊM học sinh có MaLop chưa tồn tại trong bảng Lop. Không thể XOÁ lớp khi còn học sinh tham chiếu tới nó (mặc định).","Đó là cách hệ quản trị bảo đảm dữ liệu luôn nhất quán."]},{"h":"UPDATE và DELETE cẩn thận","p":["UPDATE/DELETE không có WHERE sẽ tác động lên TẤT CẢ các dòng. Hãy thử bằng SELECT với cùng điều kiện WHERE trước khi chạy."],"code":"UPDATE LuotThue SET SoGio = SoGio + 1 WHERE MaKT = \"K001\";","lang":"sql"},{"h":"Chọn kiểu dữ liệu","p":["Số điện thoại, mã vạch là định danh → kiểu xâu để giữ số 0 đầu. Điểm, giá tiền → kiểu số để so sánh và tính trung bình. Ngày tháng → DATE.","Nếu lưu số bằng xâu thì \"10\" đứng trước \"9\" khi sắp xếp."]}],"traps":[["Khoá ngoài xác định duy nhất bản ghi.","Đó là khoá chính."],["Có thể thêm dòng con với khoá ngoài chưa có ở bảng cha.","Bị từ chối bởi ràng buộc toàn vẹn."],["Lưu số điện thoại kiểu số nguyên.","Dùng xâu để giữ số 0 đầu."]],"tip":"Nhớ: khoá chính để NHẬN DIỆN, khoá ngoài để NỐI.","min":5},"complexity":{"t":"Đánh giá độ phức tạp thời gian","tags":["do-phuc-tap"],"intro":"Bạn hay thấy hai vòng for lồng nhau là kết luận O(n²) mà không xem vòng trong thật sự chạy bao nhiêu lần.","steps":[{"h":"Độ phức tạp là gì?","p":["Là cách số phép toán cơ bản tăng lên khi kích thước dữ liệu n tăng. Ta bỏ hệ số hằng và các số hạng bậc thấp: 3n² + 5n + 7 → O(n²).","Các mức hay gặp, từ nhanh đến chậm: O(1), O(log n), O(n), O(n log n), O(n²), O(2ⁿ)."],"fig":"complexity"},{"h":"Cách đếm vòng lặp","p":["Vòng đơn chạy n lần → O(n). Hai vòng lồng: nhân số lần, NHƯNG phải xem vòng trong chạy bao nhiêu lần (hằng số, n, hay phụ thuộc i).","Biến lặp nhân/chia đôi (i *= 2) → O(log n). Hai khối nối tiếp → cộng rồi lấy số hạng lớn nhất."]},{"h":"Ví dụ vòng lồng \"lệch\"","p":["Vòng trong nhảy bước i nên chạy khoảng n/i lần. Hãy đếm bằng tay với n = 8 rồi kiểm tra bằng máy."],"fig":"loops","code":"ops = 0\nfor i in range(1, 8):\n    j = i\n    while j < 8:\n        ops += 1\n        j += i\nprint(ops)","lang":"py","out":"16"},{"h":"Kết luận","p":["Tổng ≈ n(1 + 1/2 + 1/3 + …) ≈ n·ln n nên độ phức tạp là O(n log n), nhỏ hơn nhiều so với O(n²).","Khi n = 100 000: log n ≈ 17, n² = 10 tỉ — chênh lệch rất lớn."]}],"traps":[["Hai vòng lồng nhau → luôn O(n²).","Phải xem vòng trong chạy mấy lần."],["O(n log n) lúc nào cũng nhanh hơn O(n²).","Chỉ đúng khi n đủ lớn; O chỉ nói về tốc độ tăng."],["i *= 2 là O(n).","Là O(log n)."]],"tip":"Hãy đếm thật với n nhỏ (n = 8) rồi nhận ra quy luật.","min":5},"search":{"t":"Tìm kiếm tuần tự và nhị phân","tags":["tim-kiem"],"intro":"Bạn hay dùng tìm nhị phân cho dãy chưa sắp xếp, hoặc đếm sai số lần so sánh.","steps":[{"h":"Hai cách tìm","p":["Tuần tự: duyệt từng phần tử, O(n), dùng được với mọi dãy. Trung bình khoảng (n+1)/2 phép so sánh.","Nhị phân: CHỈ dùng khi dãy đã sắp xếp. Mỗi lần so sánh với phần tử giữa, bỏ đi một nửa miền tìm: tối đa ⌊log₂ n⌋ + 1 lần."],"fig":"bsearch"},{"h":"Chạy từng bước","p":["Dãy 15 số, tìm 23: m = (l + r)//2. Lần 1 m = 7 (56 > 23 → r = m − 1); lần 2 m = 3 (12 < 23 → l = m + 1); lần 3 m = 5 → trúng."],"code":"a = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91, 95, 99, 104, 110, 120]\nl, r, dem = 0, len(a) - 1, 0\nwhile l <= r:\n    m = (l + r) // 2\n    dem += 1\n    if a[m] == 23:\n        break\n    if a[m] < 23:\n        l = m + 1\n    else:\n        r = m - 1\nprint(m, dem)","lang":"py","out":"5 3"},{"h":"Hai lỗi hay gặp","p":["Điều kiện lặp phải là l <= r (không phải l < r), nếu không sẽ bỏ sót trường hợp còn đúng một phần tử.","Cập nhật phải là l = m + 1 hoặc r = m − 1; viết l = m dễ gây lặp vô hạn."]}],"traps":[["Nhị phân dùng được cho dãy bất kì.","Phải sắp xếp trước."],["n = 100 000 cần 50 000 lần so sánh.","Chỉ tối đa 17 lần."],["Viết while l < r.","Phải là l <= r."]],"tip":"Nhị phân = \"đoán số\": mỗi lần đoán số giữa rồi loại một nửa.","min":5},"sort":{"t":"Sắp xếp chọn, chèn, nổi bọt","tags":["sap-xep","thuat-toan"],"intro":"Bạn hay nhầm ba thuật toán với nhau và suy diễn sai trạng thái sau k lượt.","steps":[{"h":"Sắp xếp chọn","p":["Mỗi lượt tìm số NHỎ NHẤT của phần chưa sắp xếp rồi đổi chỗ với phần tử đầu phần đó. Luôn n(n−1)/2 phép so sánh, tối đa n−1 lần đổi chỗ."],"fig":"ssort","code":"a = [29, 10, 14, 37, 13]\nfor i in range(2):\n    m = min(range(i, len(a)), key=lambda j: a[j])\n    a[i], a[m] = a[m], a[i]\nprint(a)","lang":"py","out":"[10, 13, 14, 37, 29]"},{"h":"Sắp xếp chèn","p":["Lấy phần tử a[i], dịch các phần tử lớn hơn nó sang phải rồi chèn vào chỗ trống. Tốt nhất O(n) (dãy đã sắp xếp), xấu nhất O(n²). Ổn định."]},{"h":"Sắp xếp nổi bọt","p":["So sánh cặp kề nhau, đổi chỗ nếu sai thứ tự; số lớn dần \"nổi\" về cuối. Nếu một lượt không đổi chỗ nào thì dừng (nên dãy đã sắp xếp chỉ tốn 1 lượt). Ổn định."]},{"h":"Nhận diện nhanh trong đoạn mã","p":["Tìm phần tử nhỏ nhất rồi đổi chỗ → chọn. Dịch các phần tử sang phải rồi chèn → chèn. So sánh a[j] và a[j+1] → nổi bọt. Khi đề cho trạng thái \"sau k lượt\", hãy vẽ lại từng lượt, đừng suy diễn từ kết quả cuối."]}],"traps":[["Sắp xếp chọn nhanh khi dãy đã sắp xếp.","Vẫn n² phép so sánh."],["Chọn và chèn giống nhau.","Chọn đổi chỗ xa; chèn dịch chuyển."],["Bỏ qua việc vẽ từng lượt.","Hãy ghi lại mảng sau mỗi lượt."]],"tip":"Nhớ: Chọn = \"chọn nhỏ nhất\", Chèn = \"chèn vào chỗ\", Nổi bọt = \"so cặp kề\".","min":5},"recursion":{"t":"Đệ quy: điều kiện dừng, số lần gọi","tags":["de-quy"],"intro":"Bạn hay đếm sai số lần gọi, hoặc không thấy vì sao đệ quy chậm.","steps":[{"h":"Hai thành phần bắt buộc","p":["Điều kiện dừng (trường hợp cơ sở) và bước thu nhỏ bài toán. Thiếu một trong hai thì chạy vô hạn → RecursionError."]},{"h":"Vẽ cây lời gọi","p":["Với f(n) = f(n−1) + f(n−2), f(0) = f(1) = 1. Mỗi f(n) gọi hai hàm con. Hãy vẽ cây rồi đếm các nút (mỗi nút là một lời gọi)."],"fig":"recursion","code":"dem = 0\ndef f(n):\n    global dem\n    dem += 1\n    return 1 if n <= 1 else f(n - 1) + f(n - 2)\nf(6)\nprint(dem)","lang":"py","out":"25"},{"h":"Công thức đếm","p":["C(n) = 1 + C(n−1) + C(n−2), với C(0) = C(1) = 1: C(2) = 3, C(3) = 5, C(4) = 9, C(5) = 15, C(6) = 25.","Hai lời gọi con cỡ n−1 → O(2ⁿ) vì cùng một giá trị bị tính lặp lại. Dùng bộ nhớ (memo) sẽ giảm xuống O(n)."]},{"h":"Cách đoán độ phức tạp","p":["Một lời gọi con cỡ n−1 → O(n). Một lời gọi cỡ n/2 → O(log n). Hai lời gọi cỡ n/2 và việc ghép tốn n → O(n log n). Độ sâu đệ quy cũng tốn bộ nhớ ngăn xếp."]}],"traps":[["Quên tính lời gọi đầu tiên.","Số nút của cây = số lời gọi."],["Nhầm giá trị trả về với số lần gọi.","Đây là hai đại lượng khác nhau."],["Cho rằng đệ quy luôn O(n).","Hai nhánh con → O(2ⁿ)."]],"tip":"Gặp bài đệ quy: vẽ cây nhỏ (n = 4) rồi mới tính.","min":5},"strings":{"t":"Xâu và danh sách: cắt lát, sao chép","tags":["xau-danh-sach","xau"],"intro":"Bạn hay đếm lệch chỉ số khi cắt lát, và tưởng b = a là sao chép.","steps":[{"h":"Chỉ số dương và âm","p":["Chỉ số dương đếm từ 0 từ đầu; chỉ số âm đếm từ cuối (−1 là phần tử cuối). Lát cắt s[a:b] lấy từ a đến TRƯỚC b; s[a:b:c] có bước c; s[::-1] đảo ngược."],"fig":"slice","code":"s = \"TinHoc11\"\nprint(s[::-1], s[1::2], s[1:-1:2], s.find(\"Hoc\"))","lang":"py","out":"11coHniT iHc1 iHc 3"},{"h":"Khả biến và bất biến","p":["Danh sách (list) khả biến: b = a chỉ tạo thêm một \"tên\" cho cùng một danh sách, nên sửa b là sửa a. a[:] hoặc a.copy() mới tạo bản sao (nông).","Xâu (str) bất biến: s.upper() trả về xâu MỚI, s không đổi."],"code":"a = [5, 2, 8]\nb = a\nc = a[:]\nb.append(7)\nprint(a, c)","lang":"py","out":"[5, 2, 8, 7] [5, 2, 8]"},{"h":"Phương thức hay gặp","p":["split() không tham số tách theo mọi dãy khoảng trắng; split(\" \") tách tại từng dấu cách và sinh xâu rỗng nếu có hai dấu cách liền nhau."]}],"traps":[["Lát cắt lấy cả chỉ số b.","Dừng TRƯỚC b."],["b = a là sao chép.","Là cùng một đối tượng."],["s.upper() thay đổi s.","s bất biến, kết quả là xâu mới."]],"tip":"Vẽ thước chỉ số 0, 1, 2… phía trên và −n…−1 phía dưới như hình, rồi tô các ô được chọn.","min":5},"matrix":{"t":"Mảng hai chiều (ma trận)","tags":["mang-2d"],"intro":"Bạn hay nhầm chỉ số hàng với cột, và không biết vì sao [[0]*3]*3 gây lỗi lạ.","steps":[{"h":"a[i][j]: hàng i, cột j","p":["Ma trận n × m có n hàng và m cột, chỉ số từ 0. Đường chéo chính có i = j; đường chéo phụ có i + j = n − 1."],"fig":"matrix"},{"h":"Bẫy khi tạo ma trận","p":["[[0]*3]*3 tạo ra ba tham chiếu tới CÙNG MỘT danh sách hàng, nên sửa một hàng là cả ba hàng cùng đổi. Cách đúng: [[0]*3 for _ in range(3)]."],"code":"a = [[0] * 3] * 3\na[0][1] = 5\nprint(a)\nb = [[0] * 3 for _ in range(3)]\nb[0][1] = 5\nprint(b)","lang":"py","out":"[[0, 5, 0], [0, 5, 0], [0, 5, 0]]\n[[0, 5, 0], [0, 0, 0], [0, 0, 0]]"},{"h":"Chuyển vị","p":["t[j][i] = a[i][j]: vòng ngoài chạy theo cột của a, vòng trong chạy theo hàng."]}],"traps":[["Tạo ma trận bằng phép nhân danh sách lồng.","Dùng danh sách sinh (list comprehension)."],["Đường chéo phụ là i + j = n.","Là i + j = n − 1 (chỉ số từ 0)."]],"tip":"Nhớ: hàng trước, cột sau — a[hàng][cột].","min":5},"scope":{"t":"Hàm, phạm vi biến, tham số mặc định","tags":["ham-pham-vi"],"intro":"Bạn hay nhầm khi nào biến trong hàm là biến mới, khi nào là biến toàn cục.","steps":[{"h":"Cục bộ và toàn cục","p":["Gán giá trị cho một biến BÊN TRONG hàm tạo ra biến cục bộ mới (che biến toàn cục cùng tên). Muốn sửa biến toàn cục phải khai báo global."],"fig":"scope","code":"x = 7\ndef g():\n    x = 3\n    return x * 2\ndef h():\n    global x\n    x = x + 1\ny = g()\nh()\nprint(x, y)","lang":"py","out":"8 6"},{"h":"Thiếu global","p":["Nếu bỏ dòng global x trong h(), Python hiểu x là biến cục bộ nhưng lại dùng nó trước khi gán → UnboundLocalError."]},{"h":"Tham số mặc định chỉ được tạo một lần","p":["def them(x, ds=[]) dùng chung MỘT danh sách cho mọi lần gọi. Cách an toàn: ds=None rồi tạo danh sách mới bên trong."],"code":"def them(x, ds=[]):\n    ds.append(x)\n    return ds\nprint(them(1), them(2))","lang":"py","out":"[1, 2] [1, 2]"}],"traps":[["Gán trong hàm là sửa biến toàn cục.","Gán tạo biến cục bộ."],["Danh sách mặc định mới được tạo mỗi lần gọi.","Chỉ tạo một lần."]],"tip":"Đọc code: thấy phép gán trong hàm thì tự hỏi \"có global không?\"","min":5},"ds":{"t":"Ngăn xếp (LIFO) và hàng đợi (FIFO)","tags":["cau-truc-du-lieu","ctdl"],"intro":"Bạn hay nhầm thứ tự lấy ra, và không biết vì sao list.pop(0) chậm.","steps":[{"h":"Hai cấu trúc","p":["Ngăn xếp: vào sau – ra trước (LIFO), thao tác ở một đầu: append / pop. Hàng đợi: vào trước – ra trước (FIFO): thêm ở cuối, lấy ở đầu."],"fig":"stackqueue"},{"h":"Ví dụ ngoặc cân bằng","p":["Duyệt xâu: gặp ngoặc mở thì đẩy vào ngăn xếp; gặp ngoặc đóng thì lấy ngoặc mở trên đỉnh ra so khớp. Xâu \"([)]\" sai vì khi gặp \")\" đỉnh là \"[\"."]},{"h":"Chi phí","p":["list.append và list.pop() ở cuối: O(1). list.pop(0) phải dịch cả danh sách: O(n). Hàng đợi dùng collections.deque với popleft() O(1). pop() trên danh sách rỗng gây IndexError."]}],"traps":[["Nhầm LIFO với FIFO.","Ngăn xếp: lấy phần tử vào sau cùng."],["Dùng list.pop(0) cho hàng đợi lớn.","Dùng deque."]],"tip":"Ngăn xếp như chồng đĩa, hàng đợi như xếp hàng mua vé.","min":5},"trace":{"t":"Đọc mã: bảng theo dõi biến","tags":["tinh-toan","vong-lap","bieu-thuc","kiem-thu","sua-loi","nhan-dinh","loi-chay","thuat-toan-nc"],"intro":"Bạn hay \"đoán\" kết quả thay vì chạy từng bước, nên lệch một đơn vị hoặc quên giá trị cuối của biến lặp.","steps":[{"h":"Lập bảng theo dõi","p":["Mỗi dòng của bảng là một lần lặp, mỗi cột là một biến. Điền từng bước, không bỏ bước nào. Đây là cách duy nhất chắc chắn với bài đọc mã."],"code":"s = 0\nfor i in range(10, 0, -3):\n    s += i\nprint(s, i)","lang":"py","out":"22 1"},{"h":"Lần lượt từng lần lặp","p":["range(10, 0, -3) cho i = 10, 7, 4, 1 (dừng trước 0). Bảng: i=10 → s=10; i=7 → s=17; i=4 → s=21; i=1 → s=22. Sau vòng for, i giữ giá trị cuối là 1."]},{"h":"Các điểm hay sai","p":["range(a, b) không gồm b. Phép // làm tròn xuống (−7 // 2 = −4); % cùng dấu với số chia (−7 % 3 = 2). round(2.5) = 2 vì Python làm tròn về số chẵn khi hoà. ** kết hợp từ phải sang trái: 2 ** 3 ** 2 = 512."],"code":"print(-7 // 2, -7 % 3, round(2.5), round(3.5), 2 ** 3 ** 2, 10 / 5)","lang":"py","out":"-4 2 2 4 512 2.0"},{"h":"Chọn bộ dữ liệu thử tốt","p":["Thử giá trị ở BIÊN (đúng ngưỡng, sát ngưỡng hai phía), trường hợp đặc biệt (rỗng, một phần tử, trùng, 0, số âm). Kiểm thử chỉ phát hiện lỗi, không chứng minh chương trình đúng."]}],"traps":[["Đoán kết quả không cần chạy từng bước.","Luôn lập bảng theo dõi."],["range(1, 5) gồm cả 5.","Dừng trước 5."],["Thử nhiều giá trị \"ở giữa\" là đủ.","Cần thử giá trị biên."]],"tip":"Ghi từng bước ra giấy; sai một đơn vị thường nằm ở biên của range hoặc điều kiện.","min":5},"ip":{"t":"Địa chỉ IP, mặt nạ mạng con, băng thông","tags":["mang-ip","mang-bang-thong"],"intro":"Bạn hay quên trừ 2 địa chỉ đặc biệt, hoặc không biết một máy thuộc mạng con nào.","steps":[{"h":"Mặt nạ /k chia địa chỉ làm hai phần","p":["/26 nghĩa là 26 bit đầu là phần MẠNG, 32 − 26 = 6 bit cuối là phần MÁY. Cùng mạng con ⇔ phần mạng giống nhau."],"fig":"ipmask"},{"h":"Tính từng bước","p":["Số địa chỉ trong mạng con = 2⁶ = 64; số máy dùng được = 64 − 2 = 62 (trừ địa chỉ mạng và địa chỉ quảng bá).","Với /26 các khối là 0–63, 64–127, 128–191, 192–255 ở byte cuối. 192.168.10.77 thuộc khối 64–127 → địa chỉ mạng .64, quảng bá .127."],"code":"import ipaddress\nn = ipaddress.ip_interface(\"192.168.10.77/26\")\nprint(n.network, n.network.broadcast_address, n.network.num_addresses - 2)","lang":"py","out":"192.168.10.64/26 192.168.10.127 62"},{"h":"Băng thông và thời gian truyền","p":["Thời gian = dung lượng / băng thông, nhưng phải đổi cùng đơn vị: 1 byte = 8 bit. Tải 600 MB qua 100 Mbps: 600 × 8 / 100 = 48 giây."]},{"h":"Dải địa chỉ riêng","p":["10.0.0.0/8, 172.16.0.0 – 172.31.255.255, 192.168.0.0/16. Chú ý 172.32.x.x KHÔNG phải địa chỉ riêng."]}],"traps":[["Số máy dùng được = 2^(32−k).","Phải trừ 2."],["Quên đổi byte ra bit.","Nhân 8."],["172.32.0.1 là địa chỉ riêng.","Dải riêng chỉ đến 172.31."]],"tip":"Gặp /k, hãy tính kích thước khối = 2^(32−k) rồi chia byte cuối thành các khối.","min":5},"netdev":{"t":"Thiết bị mạng và giao thức","tags":["tbmang","thietbi","giaothuc"],"intro":"Bạn hay nhầm hub – switch – router, và nhầm các giao thức thư (SMTP, POP3, IMAP).","steps":[{"h":"Hub, switch, router khác nhau ở chỗ nào?","p":["Hub: nhận tín hiệu rồi phát ra MỌI cổng (dễ xung đột). Switch: học địa chỉ MAC và chỉ chuyển tới ĐÚNG cổng chứa máy đích. Router: nối các mạng với nhau, chọn đường đi cho gói tin theo địa chỉ IP."],"fig":"netdev"},{"h":"Các thiết bị còn lại","p":["Modem: biến đổi tín hiệu số ↔ tín hiệu của đường truyền (cáp, quang). Repeater: khuếch đại tín hiệu yếu. Access point (AP): phát sóng Wi-Fi cho thiết bị không dây."]},{"h":"Giao thức hay gặp","p":["SMTP gửi thư; POP3/IMAP nhận thư. DNS đổi tên miền ↔ địa chỉ IP. HTTP truyền trang web. ICMP dùng cho lệnh ping. TCP bảo đảm truyền tin cậy; IP đánh địa chỉ và dẫn đường.","Thứ tự mở một trang web: DNS (tìm IP) → kết nối TCP → gửi yêu cầu HTTP."]}],"traps":[["Router chỉ khuếch đại tín hiệu.","Đó là repeater; router định tuyến."],["HTTP dùng để nhận thư.","POP3/IMAP nhận thư; HTTP truyền trang web."],["Ping dùng DNS.","Ping dùng ICMP."]],"tip":"Nhớ: Hub = loa phát thanh, Switch = đưa thư đúng nhà, Router = bưu điện nối các thành phố.","min":5},"confusion":{"t":"Học máy: ma trận nhầm lẫn, precision, recall","tags":["ml-danhgia","khdl-thongke","khdl-lamsach"],"intro":"Bạn hay nhầm FP với FN, và dùng accuracy khi dữ liệu mất cân bằng.","steps":[{"h":"Bốn ô của ma trận nhầm lẫn","p":["Chọn một lớp làm \"lớp dương\" (ví dụ thư rác). TP: đúng là rác, báo rác. FN: rác thật nhưng bị bỏ sót. FP: thư thường bị báo nhầm là rác. TN: thư thường, báo thường."],"fig":"confusion"},{"h":"Ba độ đo","p":["Precision = TP/(TP+FP): trong số mô hình báo \"rác\", có bao nhiêu đúng. Recall = TP/(TP+FN): trong số rác thật, bắt được bao nhiêu. Accuracy = (TP+TN)/tổng."],"code":"TP, FP, FN, TN = 24, 6, 16, 54\nprint(TP / (TP + FP), TP / (TP + FN), (TP + TN) / 100)","lang":"py","out":"0.8 0.6 0.78"},{"h":"Khi nào dùng độ đo nào?","p":["Dữ liệu mất cân bằng (99% là lớp thường): mô hình luôn đoán \"thường\" vẫn có accuracy 99% nhưng vô dụng. Khi đó cần xem precision và recall.","F1 là trung bình điều hoà của precision và recall."]},{"h":"Thống kê nhanh","p":["Ngoại lai kéo trung bình lệch nhiều; trung vị và yếu vị ổn định hơn. Chuẩn hoá min–max: (x − min)/(max − min) đưa dữ liệu về [0; 1]."]}],"traps":[["Nhầm FP và FN.","FP: báo nhầm là dương; FN: bỏ sót dương."],["Accuracy cao nghĩa là mô hình tốt.","Không đúng khi dữ liệu mất cân bằng."]],"tip":"Câu hỏi nhớ: Precision nhìn vào CÁC CA BÁO DƯƠNG; Recall nhìn vào CÁC CA DƯƠNG THẬT.","min":5},"overfit":{"t":"Học máy: quá khớp, tập kiểm thử, rò rỉ dữ liệu","tags":["ml-khainiem","ml","ml-knn","ml-hoiquy","ml-kmeans","mo-phong"],"intro":"Bạn hay nhầm quá khớp với dưới khớp, và không phân biệt học có giám sát với không giám sát.","steps":[{"h":"Quá khớp nhìn qua đồ thị","p":["Mô hình càng phức tạp thì sai số trên tập huấn luyện càng giảm. Nhưng sai số trên tập kiểm thử giảm rồi LẠI TĂNG: mô hình học thuộc cả nhiễu của dữ liệu huấn luyện → quá khớp."],"fig":"overfit"},{"h":"Cách nhận biết và khắc phục","p":["Dấu hiệu: tốt (ví dụ 99%) trên tập huấn luyện, kém (ví dụ 70%) trên tập kiểm thử. Khắc phục: thêm dữ liệu, đơn giản hoá mô hình, kiểm định chéo.","Dưới khớp thì ngược lại: kém ở cả hai tập vì mô hình quá đơn giản."]},{"h":"Rò rỉ dữ liệu","p":["Không dùng thông tin của tập kiểm thử khi huấn luyện, chọn tham số hay chuẩn hoá. Nếu không, điểm kiểm thử đẹp nhưng không phản ánh dữ liệu thật."]},{"h":"Phân loại các bài toán","p":["Có giám sát: dữ liệu có nhãn (phân loại, hồi quy). Không giám sát: không có nhãn (phân cụm k-means). Hồi quy dự đoán giá trị số liên tục; phân loại dự đoán nhãn rời rạc. k-NN dự đoán theo nhãn đa số của k láng giềng gần nhất; k = 1 dễ quá khớp."]}],"traps":[["Huấn luyện 99%, kiểm thử 70% là dưới khớp.","Đó là quá khớp."],["k-means cần dữ liệu có nhãn.","Phân cụm không cần nhãn."]],"tip":"Quá khớp = \"học vẹt\": giỏi bài đã học, kém bài mới.","min":5}};
